// casCommandError maps a raw CAS error into the wire-format reason string
// reported to the pushing client. It preserves the previous per-action
// phrasing so the report-status output is unchanged.
func casCommandError(cmd *packp.Command, err error) error {
	// A directory/file conflict reports as ErrReferenceHasChanged but carries
	// the "ref name conflicts with an existing ref namespace" reason — surface
	// it before the generic mapping below would flatten it to "already exists".
	if errors.Is(err, refstore.ErrDirFileConflict) {
		return refstore.ErrDirFileConflict
	}
	if errors.Is(err, gogit_storage.ErrReferenceHasChanged) {
		if gitwire.CommandAction(cmd) == packp.Create {
			return errors.New("already exists")
		}
		return errors.New("remote ref has changed")
	}
	switch gitwire.CommandAction(cmd) { //nolint:exhaustive // Invalid is not a valid push action
	case packp.Create:
		return fmt.Errorf("create %s: %w", cmd.Name, err)
	case packp.Update:
		return fmt.Errorf("update %s: %w", cmd.Name, err)
	case packp.Delete:
		return fmt.Errorf("delete %s: %w", cmd.Name, err)
	}
	return err
}

